 async #executeInteraction(p,a,eventOptions={}){const id=p.id;
  if(this.snapshot().enhancedLeague?.phase==='active'&&p.kind!=='enhanced-league')throw Error('강화 리그 도전을 마치거나 중도 포기한 뒤 이용하세요.');
  if(p.kind==='legacy-location-info')return {message:p.message,supersededBy:p.supersededBy,readOnly:true};
  if(p.kind==='enhanced-league'){if(a.type==='next')return this.story.runEnhancedLeagueOpponent(this.options({attempt:a.attempt,index:a.index}));return this.story.enhancedLeagueCommand(a)}
  if(p.kind==='enhanced-league-info')return {message:'본편 챔피언 승리와 POST 해금 후 계룡산 리그 입구에서 강화 리그에 도전하세요.'};
  if(p.kind==='yeji-final'){if(!worldGate(this.snapshot(),this.story.contract,p.gate))throw Error('YEJI_FINAL_GATE_LOCKED');return this.story.runYejiFinal(this.options())}
  if(p.kind==='route-checkpoint'){await this.story.worldCommand({type:'interaction',pointId:id});return {message:p.message}}
  if(p.kind==='harin-rematch'){if(a.type!=='challenge')return {message:'하린: 센터에서 준비한 뒤 다시 대결해 볼래?'};return this.story.runHarinRematch(this.options({sequence:a.sequence}))}
  if(p.kind==='warp'){if(p.exit&&!this.snapshot().progress.completedStages.includes(p.stageId))await this.story.completeStage(p.stageId);if(!worldStageAccess(this.snapshot(),this.story.contract,this.definition.maps[p.targetMapId].stageId)||!worldGate(this.snapshot(),this.story.contract,p.gate))throw Error('WORLD_GATE_LOCKED');await this.story.worldCommand({type:'warp',pointId:id});unlockField(this.field);return}
  if(p.kind==='puzzle'){await this.story.worldCommand({type:'puzzle',pointId:id});return {message:this.snapshot().world.puzzles.includes(p.puzzleId)?'관장 통로가 열려 있습니다. 북쪽 관장을 만난 뒤 같은 입구로 돌아갈 수 있어요.':p.message}}if(p.kind==='landmark'&&p.message){await this.story.worldCommand({type:'interaction',pointId:id});return {message:p.message}}if(p.kind==='event')return this.story.runEvent(p.eventId,this.options(eventOptions));if(p.kind==='trainer'){const trainer=this.story.contract.trainers[p.trainerId];if(!trainer?.repeatable&&this.snapshot().progress.defeatedTrainers.includes(p.trainerId)){const actor=this.field.core.npcs.find(n=>n.canonicalTrainerId===p.trainerId);return {message:actor?.afterDialogue??'조사를 응원해요.',alreadyDefeated:true,trainerId:p.trainerId}}return this.story.runTrainer(p.trainerId,this.options(eventOptions))}if(p.kind==='post-deferred')throw Error(p.reason);
  if(p.kind==='tutorial'){eventOptions.nativePrologueFieldRejectOnly?.();await this.story.enterArea(p.areaId,null);eventOptions.nativePrologueFieldAfterArea?.();eventOptions.nativePrologueFieldRejectOnly?.();return this.story.runTutorialCapture(this.options(eventOptions))}
  if(p.kind==='fishing'){const s=this.snapshot(),cell=positionCell(s.position);if((!eventOptions.nativeS2CoastFishing&&(cell.x!==p.x||cell.y!==p.y||s.position.facing!==p.facing))||!tileAt(this.map,...p.water).water)throw Error('낚시 표식 위에서 남쪽 물을 향하세요.');if(!p.rods.includes(a.rod))throw Error('Invalid fishing rod');eventOptions.nativeS2RejectOnly?.();if(!eventOptions.nativeS2AreaPrepared)await this.story.enterArea(p.areaId,null);eventOptions.nativeS2RejectOnly?.();return this.story.fish(a.rod,this.options(eventOptions))}
  if(p.kind==='acquisition'){eventOptions.nativeS4GameplayRejectOnly?.();eventOptions.nativeS2RejectOnly?.();if(!eventOptions.nativeS2AreaPrepared){await this.story.enterArea(p.areaId,null);if(p.requirements.includes('story_evening_survey'))await this.story.surveyAcquisition(p.acquisitionId)}eventOptions.nativeS4GameplayRejectOnly?.();eventOptions.nativeS2RejectOnly?.();return this.story.acquire(p.acquisitionId,this.options({...eventOptions,tradeInstanceId:a.tradeInstanceId}))}if(p.kind==='compass')return this.story.assembleCompass();
  if(p.kind==='hidden-geoje'){const claimed=!!this.snapshot().geojeHidden?.receipts[p.slotId];await this.story.worldCommand({type:'hidden-geoje',pointId:id});return {message:claimed?'이미 조사한 보관함입니다.':'거제볼 1개를 발견했습니다!'}}
  if(p.kind==='hidden-marker'){await this.story.worldCommand({type:'hidden-marker',pointId:id});return {message:p.message}}
  if(['hidden-clue','hidden-hint-npc'].includes(p.kind)){await this.story.worldCommand({type:'interaction',pointId:id});return {message:p.message}}
  if(p.kind==='shop'){if(!activeEconomyPolicy(this.snapshot(),this.catalog)){quotePurchase(this.snapshot(),this.catalog.itemContract,a.itemId,a.quantity);throw Error('일반 세션의 자금·재고 정책은 승인 대기입니다.')}return this.story.economyCommand({type:'purchase',transactionId:a.transactionId,hubId:p.hubId,itemId:a.itemId,quantity:a.quantity})}
  if(p.kind==='heal'){if(a.type==='storage-exchange')return this.story.worldCommand({type:a.type,pointId:id,partyInstanceId:a.partyInstanceId,boxInstanceId:a.boxInstanceId});if(!a.type||a.type==='heal'){await this.story.worldCommand({type:'visit-hub',pointId:id});if(this.#selectedHealGrant!==null&&!validateSelectedHealGrant(this.#selectedHealGrant,this,this.snapshot(),id))throw Error('SELECTED_HEAL_AUTHORITY_REJECTED');if(this.#nativeGrant!==null&&!validatePostHealGrant(this.#nativeGrant,this,this.snapshot(),id))throw Error('NATIVE_HEAL_AUTHORITY_REJECTED');return activeEconomyPolicy(this.snapshot(),this.catalog)?this.story.economyCommand({type:'heal',transactionId:a.transactionId,hubId:p.hubId}):this.story.recoverParty()}if(!['ball-aid','research-accept','research-report'].includes(a.type))throw Error('Unknown center action');return this.story.economyCommand({type:a.type,hubId:p.hubId,transactionId:a.transactionId,round:a.round})}
  if(p.kind==='research')return this.story.economyCommand({type:'observe',transactionId:a.transactionId,pointId:id,round:this.snapshot().economy.quest.round});return this.story.worldCommand({type:'interaction',pointId:id});
 }
